{"filename":"script.js","content":"(function(){
  const apiBase="/api";
  const pages={};

  function registerPage(slug,renderer){pages[slug]=renderer;}

  function apiRequest(method,path,data){
    const opts={method,headers:{"Content-Type":"application/json"}};
    if(data!==undefined){opts.body=JSON.stringify(data);}
    return fetch(apiBase+path,opts).then(res=>{
      if(!res.ok){return res.json().then(err=>Promise.reject(err));}
      return res.json();
    });
  }

  const api={
    get:path=>apiRequest("GET",path),
    post:(path,data)=>apiRequest("POST",path,data)
  };

  function setTitle(title){
    const el=document.getElementById("page-title");
    if(el){el.textContent=title;}
  }

  function showToast(message,type="info"){
    const toast=document.createElement("div");
    toast.className=`toast toast-${type}`;
    toast.textContent=message;
    document.body.appendChild(toast);
    setTimeout(()=>toast.remove(),3000);
  }

  function capitalize(s){return s.charAt(0).toUpperCase()+s.slice(1);}

  function render(slug){
    const root=document.getElementById("main");
    if(!root){return;}
    const renderer=pages[slug];
    if(!renderer){
      root.innerHTML="<p>Page not found.</p>";
      setTitle("Not Found");
      return;
    }
    const profile={};
    const search=document.getElementById("global-search")?.value||"";
    renderer({root,profile,api,search});
    setTitle(capitalize(slug));
  }

  function onHashChange(){
    const hash=location.hash||"#/home";
    const slug=hash.replace(/^#\/?/,'').split('?')[0]||"home";
    render(slug);
  }

  window.ForgeAI={registerPage};

  document.addEventListener("DOMContentLoaded",()=>{
    document.querySelectorAll("#sidebar .nav-link").forEach(a=>{
      a.addEventListener("click",()=>{
        document.querySelectorAll("#sidebar .nav-link.active").forEach(el=>el.classList.remove("active"));
        a.classList.add("active");
      });
    });
    onHashChange();
    window.addEventListener("hashchange",onHashChange);
  });
})();"}
